import{c as a,Q as t,j as e,m as i}from"./chunks/framework.8JjYC3xy.js";const u=JSON.parse('{"title":"第十七章：权限模式与自动执行","description":"五种权限模式、Shift+Tab 切换、自动模式的分类器边界，以及计划模式怎么用","frontmatter":{"title":"第十七章：权限模式与自动执行","description":"五种权限模式、Shift+Tab 切换、自动模式的分类器边界，以及计划模式怎么用","lastVerified":"2026-02-24","officialDoc":"https://code.claude.com/docs/zh-CN/permission-modes"},"headers":[],"relativePath":"guide/4-advanced-usage/17-permission-modes.md","filePath":"guide/4-advanced-usage/17-permission-modes.md"}'),o={name:"guide/4-advanced-usage/17-permission-modes.md"};function d(n,s,l,p,c,h){return t(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="第十七章-权限模式与自动执行" tabindex="-1">第十七章：权限模式与自动执行 <a class="header-anchor" href="#第十七章-权限模式与自动执行" aria-label="Permalink to &quot;第十七章：权限模式与自动执行&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">学习目标</p><p>学完这章，你知道 Claude 什么时候会自己动手、什么时候必须问你，以及怎么在&quot;少点确认&quot;和&quot;别乱来&quot;之间调到自己舒服的位置。</p></div><div class="warning custom-block"><p class="custom-block-title">概念先澄清</p><p>&quot;Agent 模式&quot;这个说法已经过时了。以前它指&quot;让 Claude 自主连续执行&quot;，现在这件事由<strong>权限模式</strong>控制：默认的自动模式（auto mode）就是让它在安全范围内自己动手。而 <strong>subagent</strong>（子代理）是另一个东西——派一个独立的助手去干一件事，见第十九章。</p></div><h2 id="五种模式-一张表看完" tabindex="-1">五种模式，一张表看完 <a class="header-anchor" href="#五种模式-一张表看完" aria-label="Permalink to &quot;五种模式，一张表看完&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>不问你就能做什么</th><th>什么时候用</th></tr></thead><tbody><tr><td><code>default</code>（界面上叫 <strong>Manual</strong>）</td><td>只能读</td><td>敏感代码、陌生项目，想逐条看</td></tr><tr><td><code>acceptEdits</code></td><td>读 + 改文件 + <code>mkdir</code>/<code>mv</code>/<code>cp</code> 这类文件操作</td><td>改自己盯着审的代码</td></tr><tr><td><code>plan</code></td><td>读 + 探索性命令，<strong>不能改文件</strong></td><td>动手前先要一份方案</td></tr><tr><td><code>auto</code>（默认）</td><td>基本一切，后台有分类器审查</td><td>长任务、不想被反复打断</td></tr><tr><td><code>dontAsk</code></td><td>只跑预批准的工具，其他一律拒绝</td><td>CI、脚本</td></tr><tr><td><code>bypassPermissions</code></td><td>一切，无审查</td><td>只在容器/虚拟机里</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">最后两种别在本地日常用</p><p><code>bypassPermissions</code> 等于把刹车拆了，官方明确只建议在隔离容器或虚拟机里用。<code>dontAsk</code> 是给 CI 用的，日常用起来会频繁被拒。</p></div><h2 id="切换-shift-tab" tabindex="-1">切换：<code>Shift + Tab</code> <a class="header-anchor" href="#切换-shift-tab" aria-label="Permalink to &quot;切换：\`Shift + Tab\`&quot;">​</a></h2><p>按一下 <code>Shift + Tab</code>，输入框下方的状态栏会变：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>⏵⏵ auto mode on        ← 默认</span></span>
<span class="line"><span>⏸ manual mode on       ← 手动，每条都问</span></span>
<span class="line"><span>⏵⏵ accept edits on     ← 改动自动通过</span></span>
<span class="line"><span>⏸ plan mode on         ← 只出方案，不改代码</span></span></code></pre></div><p>循环顺序是 <code>auto → default → acceptEdits → plan → auto</code>。</p><p>启动时指定，或设成默认：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --permission-mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plan</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 这次以计划模式启动</span></span></code></pre></div><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// .claude/settings.json —— 项目默认用计划模式</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;permissions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;defaultMode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;plan&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="自动模式到底放行了什么" tabindex="-1">自动模式到底放行了什么 <a class="header-anchor" href="#自动模式到底放行了什么" aria-label="Permalink to &quot;自动模式到底放行了什么&quot;">​</a></h2><p>它的做法是：动手前让一个分类器看一眼这个操作危险不危险。安全就过，危险就拦下来问你。</p><p><strong>默认会拦的</strong>（节选，都是日常真会碰到的）：</p><ol><li><code>curl ... | bash</code> 这类&quot;下载再执行&quot;</li><li>生产环境部署、数据库迁移、<code>terraform destroy</code> 之类的销毁操作</li><li><code>git push --force</code>、<code>git reset --hard</code>、<code>git clean -fd</code>、<code>git stash drop</code></li><li>对别人已经推上去的提交做 <code>git commit --amend</code></li><li>批量删除云存储、改 IAM/仓库权限、改 DNS 或证书</li><li>把密钥、令牌打印到终端或写进文件</li><li>合并没有人工批准的 PR，或批准 Claude 自己开的 PR</li><li>不可逆地删除会话开始前就存在的文件</li></ol><div class="tip custom-block"><p class="custom-block-title">为什么&quot;帮我清理一下&quot;经常被拦</p><p><code>rm</code> 掉一个已经存在的文件属于不可逆操作，分类器会拦。这不是它不懂你，是安全边界在起作用。想让它清理，先把要删的清单列出来给你确认，再逐条执行。</p></div><p><strong>任何模式都不自动批准的</strong>（连 <code>bypassPermissions</code> 也拦）：显式 <code>ask</code> 规则命中的工具、需要你交互才能完成的工具、以及 <code>rm</code> 掉关键路径（如 <code>~</code>、<code>/</code>、<code>.git</code>）的操作。</p><h2 id="计划模式-动代码前先看方案" tabindex="-1">计划模式：动代码前先看方案 <a class="header-anchor" href="#计划模式-动代码前先看方案" aria-label="Permalink to &quot;计划模式：动代码前先看方案&quot;">​</a></h2><p>这是日常最值得养成的习惯。大改动之前：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/plan 把认证从 session 改成 JWT，涉及哪些文件</span></span></code></pre></div><p>它会去读代码、跑探查命令，然后给你一份计划，<strong>一行代码都不改</strong>。计划出来后你会看到三个选项：</p><ul><li><strong>Yes, and use auto mode</strong> —— 批准，然后以自动模式开始改</li><li><strong>Yes, manually approve edits</strong> —— 批准，但每处改动都让你过目</li><li><strong>No, keep planning</strong> —— 不满意，继续聊方案</li></ul><p>按 <code>Ctrl + G</code> 还能把计划拉到编辑器里直接改。</p><div class="tip custom-block"><p class="custom-block-title">一句话判断</p><p>改动超过 3 个文件、或你不确定它理解对不对 → 先 <code>/plan</code>。改一行拼写 → 直接说。</p></div><h2 id="更细的控制-权限规则" tabindex="-1">更细的控制：权限规则 <a class="header-anchor" href="#更细的控制-权限规则" aria-label="Permalink to &quot;更细的控制：权限规则&quot;">​</a></h2><p>模式是粗粒度开关。想精确到&quot;允许 <code>npm test</code>，但 <code>git push</code> 一定要问&quot;，用 <code>/permissions</code> 打开规则界面，或直接写进 <code>.claude/settings.json</code>：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;permissions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;allow&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Bash(npm test:*)&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Bash(npm run lint:*)&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;ask&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Bash(git push:*)&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;deny&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Read(./.env)&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Read(./secrets/**)&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>规则和模式是叠加关系：<strong>拒绝规则在任何模式下都生效</strong>，包括 <code>bypassPermissions</code>。</p><h2 id="再加一层-沙箱" tabindex="-1">再加一层：沙箱 <a class="header-anchor" href="#再加一层-沙箱" aria-label="Permalink to &quot;再加一层：沙箱&quot;">​</a></h2><p>模式管&quot;要不要问你&quot;，沙箱管&quot;就算它想干也访问不到&quot;。开启 Bash 沙箱后，shell 命令只能在指定目录和网络白名单里活动。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/sandbox</span></span></code></pre></div><p>沙箱 + 自动模式是推荐的组合：省掉大部分确认，同时危险动作在系统层面就被挡住。macOS、Linux、WSL2 支持内置沙箱。</p><div class="warning custom-block"><p class="custom-block-title">Windows 用户</p><p>原生 Windows 上内置 Bash 沙箱不可用。用 WSL2，或者更需要隔离时上 dev container。</p></div><h2 id="按场景选配置" tabindex="-1">按场景选配置 <a class="header-anchor" href="#按场景选配置" aria-label="Permalink to &quot;按场景选配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你的情况</th><th>建议</th></tr></thead><tbody><tr><td>第一次碰一个陌生仓库</td><td><code>manual</code>（手动）+ 先 <code>/plan</code></td></tr><tr><td>日常改自己熟悉的项目</td><td><code>auto</code>（默认）+ 关键目录设 <code>deny</code> 规则</td></tr><tr><td>做重构、动很多文件</td><td><code>plan</code> 出方案 → 批准后用 <code>auto</code> 执行</td></tr><tr><td>跑自动化脚本 / CI</td><td><code>dontAsk</code> + 明确的 <code>allow</code> 列表</td></tr><tr><td>在 Docker 里批量跑</td><td><code>bypassPermissions</code>，但必须是隔离环境</td></tr><tr><td>要跑会联网的命令</td><td>开沙箱，限制网络白名单</td></tr></tbody></table><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q: 它一直问我，很烦？</strong></p><p>A: 看状态栏确认是不是在 <code>manual</code>。按 <code>Shift + Tab</code> 切到 <code>auto</code>。如果是某条命令反复问，用 <code>/permissions</code> 把它加进 <code>allow</code>。</p><p><strong>Q: 它自己跑了个我不想让它跑的命令？</strong></p><p>A: 先 <code>Esc</code> 中断，再 <code>/rewind</code> 回滚。然后检查是不是模式开得太松，或把那条命令加进 <code>deny</code>。</p><p><strong>Q: 为什么我在 <code>auto</code> 模式下它还是问？</strong></p><p>A: 三种可能：操作被判为危险、命中了你的 <code>ask</code> 规则、或者需要你本人交互（比如填表、做选择）。</p><p><strong>Q: 自动模式可以关掉吗？</strong></p><p>A: 可以。设置 <code>permissions.defaultMode</code> 为 <code>default</code>，或让管理员在托管设置里禁用。</p><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><ol><li>按 <code>Shift + Tab</code> 把四种模式各切一遍，记下状态栏的文字变化</li><li>用 <code>/plan</code> 让它规划一个你手上的小改动，看完计划先选 &quot;No, keep planning&quot; 试试对话</li><li>用 <code>/permissions</code> 把 <code>npm test</code> 加进 allow 列表，再跑一次看是否还问</li></ol><h2 id="下一章" tabindex="-1">下一章 <a class="header-anchor" href="#下一章" aria-label="Permalink to &quot;下一章&quot;">​</a></h2><p><a href="/claude-code-guide/guide/4-advanced-usage/18-github-actions.html">👉 第十八章：GitHub Actions 集成</a></p>`,50)])])}const k=a(o,[["render",d]]);export{u as __pageData,k as default};
